import{_ as r,o as a,c as o,a2 as d}from"./chunks/framework.CYjxsSA2.js";const u=JSON.parse('{"title":"桌宠黑泽","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pet.md","filePath":"guide/pet.md"}'),e={name:"guide/pet.md"};function l(n,t,i,s,h,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="桌宠黑泽" tabindex="-1">桌宠黑泽 <a class="header-anchor" href="#桌宠黑泽" aria-label="Permalink to &quot;桌宠黑泽&quot;">​</a></h1><p><strong>黑泽</strong>是常驻在界面上的小助手 —— 不必先组织完整任务描述，直接说人话就行。</p><p>拖动可换位置，点一下打开对话；有待确认的操作时，它会主动展开对话等你处理。</p><h2 id="两种形态" tabindex="-1">两种形态 <a class="header-anchor" href="#两种形态" aria-label="Permalink to &quot;两种形态&quot;">​</a></h2><p>形态由你<strong>当前所在位置</strong>决定：</p><table tabindex="0"><thead><tr><th>形态</th><th>位置</th><th>角色</th></tr></thead><tbody><tr><td><strong>首页形态</strong></td><td>还没进任何项目</td><td><strong>项目管家</strong> —— 项目的增删改查</td></tr><tr><td><strong>项目形态</strong></td><td>已进入某个项目</td><td><strong>侦察助手</strong> —— 下发扫描、查阅漏洞与报告</td></tr></tbody></table><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><p><strong>首页形态</strong></p><ul><li>列出 / 筛选项目，查看项目详情</li><li>批量创建项目（「帮我建三个项目」）</li><li>改名、改描述</li><li>批量归档（可逆，数据保留）</li><li>批量删除（不可逆，需<strong>两次确认</strong>）</li></ul><p><strong>项目形态</strong> 在上面的基础上增加：</p><ul><li>读取项目概况、目标资产、端口扫描历史与结果，并可<strong>下发端口扫描</strong></li><li>读取空间测绘资产，并可<strong>下发测绘查询</strong></li><li>读取测绘站点、测绘发现、高价值待测清单、API 攻击面与侦察报告，并可<strong>下发漏洞测绘 / 智渗透</strong></li><li>暂停、继续、停止已下发的测绘任务</li><li><strong>只读</strong>查看漏洞账本与报告全文</li><li>资料检索：项目记忆、技能文档、联网搜索与网页抓取</li></ul><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><p>黑泽<strong>不是第二个军团</strong>：读得多，动手少。</p><ul><li>不能执行命令、不能跑脚本、不能开浏览器、不能写工作区文件</li><li>不能修改漏洞账本（账本是报告正文的权威来源，写错会污染交付物）</li><li>不能爆破凭据、不能调用工具箱、不能派发子任务</li><li>首页形态不能发起任何扫描或测绘 —— 那需要项目上下文</li></ul><p>不在能力范围内的请求，它会明确告诉你做不了，而不是勉强试试。</p><h2 id="确认策略" tabindex="-1">确认策略 <a class="header-anchor" href="#确认策略" aria-label="Permalink to &quot;确认策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>确认次数</th></tr></thead><tbody><tr><td>全部只读查询</td><td>不询问</td></tr><tr><td>创建 / 改名 / 归档项目</td><td>1 次（批量整批一次确认）</td></tr><tr><td>下发端口扫描 / 空间测绘 / 漏洞测绘</td><td>1 次（会对真实目标发请求）</td></tr><tr><td><strong>删除项目</strong></td><td><strong>2 次</strong>（不可撤销）</td></tr></tbody></table><p>拒绝的操作本回合内不再重复询问；删除时必须带上项目当前名称，名称对不上直接拒绝。</p><h2 id="交互" tabindex="-1">交互 <a class="header-anchor" href="#交互" aria-label="Permalink to &quot;交互&quot;">​</a></h2><ul><li><strong>真流式输出</strong>，逐字返回</li><li><strong>工具卡</strong> —— 调用时显示「执行中」，结束后就地替换为结果卡，展开可见真实入参与返回值</li><li><strong>确认卡在消息流末尾</strong>，不遮挡它要批的操作说明</li><li><strong>停止按钮</strong> —— 回合运行中可随时中断；单回合有步数与时长上限，到上限会给出阶段性结论</li></ul><h2 id="它改了什么-一眼可见" tabindex="-1">它改了什么，一眼可见 <a class="header-anchor" href="#它改了什么-一眼可见" aria-label="Permalink to &quot;它改了什么，一眼可见&quot;">​</a></h2><p>黑泽替你改动数据后，界面上对应的位置会<strong>高亮标注</strong>：</p><table tabindex="0"><thead><tr><th>位置</th><th>标记</th></tr></thead><tbody><tr><td>首页项目卡 / 最近项目</td><td>外框 + 右上角标</td></tr><tr><td>空间扫描任务号与扫描历史</td><td>行内角标 + 文字标记</td></tr><tr><td>空间测绘结果卡标题</td><td>行内角标</td></tr><tr><td>漏洞测绘站点表</td><td>行内角标</td></tr></tbody></table><p>标记<strong>点击即消失</strong>，并且会保留下来 —— 刷新页面、事后再进来，标记都还在。</p>',24)])])}const b=r(e,[["render",l]]);export{u as __pageData,b as default};
